var val = Environment.GetEnvironmentVariable("MY_FLAG");
if (val == null || val.Length == 0)
{
    // .NET 9 breaking change: on Linux, empty env vars now return
    // empty string "" instead of null. Check both to detect "not set".
    if (!Environment.GetEnvironmentVariables().Contains("MY_FLAG"))
